export function expandQuestions(n, originals) {
  const target = n <= 8 ? 10 : n === 14 ? 18 : n <= 26 ? 14 : 12;
  if (!Number.isInteger(n) || n < 1 || n > 32 || !Array.isArray(originals) || originals.length !== 3) {
    throw new Error(`Invalid interview source for lesson ${n}`);
  }
  const base = originals.map((item, i) => {
    const source = Array.isArray(item) ? { q: item[0], a: item[1] } : item;
    return { ...source, id: `q${i + 1}`, a: enhancedAnswers[`${n}:q${i + 1}`] ?? source.a, keyPoints: [focus[n][i]] };
  });
  const result = [...base, ...(extras[n] ?? []).map((item, i) => ({ ...item, id: `q${i + 4}` }))];
  if (result.length !== target) throw new Error(`Lesson ${n}: expected ${target} interview questions, got ${result.length}`);
  return result;
}
